package main

import (
	"fmt"
	"os"

	"github.com/hanzoai/cloud/apps"
)

// Standalone entry for the sync app — generated by cmd/gen-app-cmds, driven by the
// generate directive in apps/apps.go. Do not hand-edit: the app is the one edit
// in apps.Wire(), and this binary is regenerated. The same app also mounts into
// the unified cloud binary via apps.Wire().
func main() {
	if err := apps.ServeSingle("sync"); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}
